import type { Point2D } from './types';

/**
 * Validate that a Point2D has finite coordinates
 * @internal
 */
function isValidPoint(point: Point2D): boolean {
  return Number.isFinite(point.x) && Number.isFinite(point.y);
}

/**
 * Calculate angle between two points in radians
 *
 * Returns the angle from p1 to p2, measured counter-clockwise from the positive x-axis.
 * Range: -π to π (or -180° to 180°).
 *
 * @param p1 - Starting point
 * @param p2 - Ending point
 * @returns Angle in radians
 * @throws Error if any coordinate is NaN or Infinity
 *
 * @example
 * ```typescript
 * const angle = angle({ x: 0, y: 0 }, { x: 1, y: 0 });
 * console.log(angle); // Returns 0 (pointing right)
 *
 * const angle2 = angle({ x: 0, y: 0 }, { x: 0, y: 1 });
 * console.log(angle2); // Returns π/2 (pointing up)
 * ```
 */
export function angle(p1: Point2D, p2: Point2D): number {
  if (!isValidPoint(p1) || !isValidPoint(p2)) {
    throw new Error('Point coordinates must be finite numbers');
  }

  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  return Math.atan2(dy, dx);
}

import type { Point2D } from './types';

/**
 * Validate that a Point2D has finite coordinates
 * @internal
 */
function isValidPoint(point: Point2D): boolean {
  return Number.isFinite(point.x) && Number.isFinite(point.y);
}

/**
 * Clamp velocity to a maximum magnitude
 *
 * Useful for gesture-based animations to prevent overly fast movements.
 * Preserves velocity direction while limiting magnitude.
 *
 * @param velocity - Velocity vector (x, y)
 * @param maxVelocity - Maximum velocity magnitude (must be positive and finite)
 * @returns Clamped velocity vector
 * @throws Error if velocity coordinates are NaN or Infinity
 * @throws Error if maxVelocity is not a positive finite number
 *
 * @example
 * ```typescript
 * const velocity = { x: 100, y: 100 };
 * const clamped = clampVelocity(velocity, 50);
 * // Returns { x: ~35.36, y: ~35.36 } (magnitude = 50)
 * ```
 */
export function clampVelocity(velocity: Point2D, maxVelocity: number): Point2D {
  if (!isValidPoint(velocity)) {
    throw new Error('Velocity coordinates must be finite numbers');
  }
  if (!Number.isFinite(maxVelocity) || maxVelocity < 0) {
    throw new Error('maxVelocity must be a non-negative finite number');
  }

  const magnitude = Math.sqrt(velocity.x * velocity.x + velocity.y * velocity.y);

  if (magnitude <= maxVelocity) {
    return velocity;
  }

  // Scale down to max velocity while preserving direction
  const scale = maxVelocity / magnitude;
  return {
    x: velocity.x * scale,
    y: velocity.y * scale,
  };
}

import type { SpringConfig, SpringState } from './types';

/**
 * Create a spring physics calculator for smooth animations
 *
 * Uses spring-damper physics to calculate position and velocity over time.
 * The spring equation is: F = -k * x - c * v
 * where k is stiffness, x is displacement, c is damping, and v is velocity.
 *
 * @param from - Starting value
 * @param to - Target value
 * @param config - Spring configuration (mass, stiffness, damping, velocity)
 * @returns Function that calculates spring state at a given time (in seconds)
 *
 * @example
 * ```typescript
 * const spring = createSpring(0, 100, { stiffness: 100, damping: 10 });
 * const state = spring(0.5); // Get state after 0.5 seconds
 * console.log(state.position); // Current position
 * console.log(state.done); // Whether spring has settled
 * ```
 */
export function createSpring(
  from: number,
  to: number,
  config: SpringConfig = {}
): (t: number) => SpringState {
  const { mass = 1, stiffness = 100, damping = 10, velocity = 0 } = config;

  // Validate inputs
  if (mass <= 0) {
    throw new Error('Spring mass must be positive');
  }
  if (stiffness < 0) {
    throw new Error('Spring stiffness must be non-negative');
  }
  if (damping < 0) {
    throw new Error('Spring damping must be non-negative');
  }

  const displacement = from - to;

  // Calculate damping ratio (zeta)
  const criticalDamping = 2 * Math.sqrt(mass * stiffness);
  const dampingRatio = damping / criticalDamping;

  // Natural frequency
  const w0 = Math.sqrt(stiffness / mass);

  // Settling threshold (when spring is considered "done")
  const SETTLE_THRESHOLD = 0.01;
  const VELOCITY_THRESHOLD = 0.01;

  return (t: number): SpringState => {
    if (t < 0) {
      return { position: from, velocity, done: false };
    }

    let position: number;
    let currentVelocity: number;

    if (dampingRatio < 1) {
      // Underdamped: oscillates before settling
      const wd = w0 * Math.sqrt(1 - dampingRatio * dampingRatio);
      const A = displacement;
      const B = (dampingRatio * w0 * displacement + velocity) / wd;
      const envelope = Math.exp(-dampingRatio * w0 * t);

      position = to + envelope * (A * Math.cos(wd * t) + B * Math.sin(wd * t));
      currentVelocity =
        envelope *
        ((-dampingRatio * w0 * A - wd * B) * Math.cos(wd * t) +
          (wd * A - dampingRatio * w0 * B) * Math.sin(wd * t));
    } else if (dampingRatio === 1) {
      // Critically damped: fastest settling without oscillation
      const A = displacement;
      const B = velocity + w0 * displacement;
      const envelope = Math.exp(-w0 * t);

      position = to + envelope * (A + B * t);
      currentVelocity = envelope * (B - w0 * (A + B * t));
    } else {
      // Overdamped: slow settling without oscillation
      const r1 = -w0 * (dampingRatio + Math.sqrt(dampingRatio * dampingRatio - 1));
      const r2 = -w0 * (dampingRatio - Math.sqrt(dampingRatio * dampingRatio - 1));
      const A = (velocity - r2 * displacement) / (r1 - r2);
      const B = displacement - A;

      position = to + A * Math.exp(r1 * t) + B * Math.exp(r2 * t);
      currentVelocity = A * r1 * Math.exp(r1 * t) + B * r2 * Math.exp(r2 * t);
    }

    // Check if spring has settled
    const positionDiff = Math.abs(position - to);
    const velocityMagnitude = Math.abs(currentVelocity);
    const done = positionDiff < SETTLE_THRESHOLD && velocityMagnitude < VELOCITY_THRESHOLD;

    return { position, velocity: currentVelocity, done };
  };
}

import type { Point2D } from './types';

/**
 * Validate that a Point2D has finite coordinates
 * @internal
 */
function isValidPoint(point: Point2D): boolean {
  return Number.isFinite(point.x) && Number.isFinite(point.y);
}

/**
 * Calculate Euclidean distance between two points
 *
 * Uses the Pythagorean theorem to calculate straight-line distance.
 *
 * @param p1 - First point
 * @param p2 - Second point
 * @returns Distance between points
 * @throws Error if any coordinate is NaN or Infinity
 *
 * @example
 * ```typescript
 * const d = distance({ x: 0, y: 0 }, { x: 3, y: 4 });
 * console.log(d); // Returns 5
 * ```
 */
export function distance(p1: Point2D, p2: Point2D): number {
  if (!isValidPoint(p1) || !isValidPoint(p2)) {
    throw new Error('Point coordinates must be finite numbers');
  }

  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  return Math.sqrt(dx * dx + dy * dy);
}

import type { EasingFunction } from './types';

/**
 * Ease-in easing function (cubic)
 *
 * Starts slowly and accelerates towards the end.
 * Approximates cubic-bezier(0.32, 0, 0.67, 0).
 *
 * @param t - Time parameter (0 to 1)
 * @returns Eased value (0 to 1)
 *
 * @example
 * ```typescript
 * const progress = easeIn(0.5); // Returns ~0.125 (accelerating)
 * const start = easeIn(0); // Returns 0
 * const end = easeIn(1); // Returns 1
 * ```
 */
export const easeIn: EasingFunction = (t: number): number => {
  // Clamp t to [0, 1]
  const clamped = Math.max(0, Math.min(1, t));

  // Cubic ease-in
  return clamped * clamped * clamped;
};

import type { EasingFunction } from './types';

/**
 * Ease-in-out easing function (cubic Bezier approximation)
 *
 * Starts slowly, accelerates in the middle, then decelerates at the end.
 * Approximates cubic-bezier(0.42, 0, 0.58, 1).
 *
 * @param t - Time parameter (0 to 1)
 * @returns Eased value (0 to 1)
 *
 * @example
 * ```typescript
 * const progress = easeInOut(0.5); // Returns ~0.5 (accelerating)
 * const start = easeInOut(0); // Returns 0
 * const end = easeInOut(1); // Returns 1
 * ```
 */
export const easeInOut: EasingFunction = (t: number): number => {
  // Clamp t to [0, 1]
  const clamped = Math.max(0, Math.min(1, t));

  // Cubic ease-in-out
  return clamped < 0.5 ? 4 * clamped * clamped * clamped : 1 - (-2 * clamped + 2) ** 3 / 2;
};

import type { EasingFunction } from './types';

/**
 * Ease-out easing function (cubic)
 *
 * Starts quickly and decelerates towards the end.
 * Approximates cubic-bezier(0.33, 1, 0.68, 1).
 *
 * @param t - Time parameter (0 to 1)
 * @returns Eased value (0 to 1)
 *
 * @example
 * ```typescript
 * const progress = easeOut(0.5); // Returns ~0.875 (decelerating)
 * const start = easeOut(0); // Returns 0
 * const end = easeOut(1); // Returns 1
 * ```
 */
export const easeOut: EasingFunction = (t: number): number => {
  // Clamp t to [0, 1]
  const clamped = Math.max(0, Math.min(1, t));

  // Cubic ease-out
  return 1 - (1 - clamped) ** 3;
};

/**
 * Motion utilities for animations and gestures
 * @module utils/motion
 */

export { angle } from './angle';
export { clampVelocity } from './clampVelocity';
export { createSpring } from './createSpring';
export { distance } from './distance';
export { easeIn } from './easeIn';
export { easeInOut } from './easeInOut';
export { easeOut } from './easeOut';
export { interpolate } from './interpolate';

export type { InterpolateOptions } from './interpolate';
export type {
  EasingFunction,
  InterpolationRange,
  Point2D,
  SpringConfig,
  SpringState,
} from './types';

/**
 * Options for the interpolate function
 */
export interface InterpolateOptions {
  /**
   * When true, clamps output to the output range bounds (prevents extrapolation).
   * When false or undefined, allows extrapolation beyond bounds.
   * @default false
   */
  clamp?: boolean;
}

/**
 * Interpolate a value from one range to another
 *
 * Maps a value from the input range to the output range using linear interpolation.
 * Supports extrapolation (values outside input range) unless `clamp` option is true.
 *
 * @param value - Value to interpolate
 * @param inputRange - Input range [min, max]
 * @param outputRange - Output range [min, max]
 * @param options - Optional configuration (e.g., { clamp: true } to prevent extrapolation)
 * @returns Interpolated value
 * @throws Error if input/output ranges have different lengths or less than 2 values
 * @throws Error if value is NaN or Infinity
 *
 * @example
 * ```typescript
 * // Map 0-100 to 0-1
 * interpolate(50, [0, 100], [0, 1]); // Returns 0.5
 *
 * // Map with extrapolation
 * interpolate(150, [0, 100], [0, 1]); // Returns 1.5
 *
 * // Map with clamping (prevents extrapolation)
 * interpolate(150, [0, 100], [0, 1], { clamp: true }); // Returns 1
 *
 * // Multi-segment interpolation
 * interpolate(50, [0, 50, 100], [0, 0.8, 1]); // Returns 0.8
 * ```
 */
/* eslint-disable security/detect-object-injection -- Array access via loop index and calculated segment index is safe */
export function interpolate(
  value: number,
  inputRange: number[],
  outputRange: number[],
  options?: InterpolateOptions
): number {
  // Validate value is a finite number
  if (!Number.isFinite(value)) {
    throw new Error('Value must be a finite number');
  }
  // Validate ranges
  if (inputRange.length !== outputRange.length) {
    throw new Error('Input and output ranges must have the same length');
  }
  if (inputRange.length < 2) {
    throw new Error('Ranges must have at least 2 values');
  }

  // Find the segment containing the value
  let segmentIndex = 0;
  for (let i = 1; i < inputRange.length; i++) {
    const prevValue = inputRange[i - 1];
    const currValue = inputRange[i];

    if (prevValue !== undefined && currValue !== undefined) {
      if (value >= prevValue && value <= currValue) {
        segmentIndex = i - 1;
        break;
      }
      if (value > currValue) {
        segmentIndex = i - 1;
      }
    }
  }

  const inputMin = inputRange[segmentIndex];
  const inputMax = inputRange[segmentIndex + 1];
  const outputMin = outputRange[segmentIndex];
  const outputMax = outputRange[segmentIndex + 1];

  // Type guards for undefined
  if (
    inputMin === undefined ||
    inputMax === undefined ||
    outputMin === undefined ||
    outputMax === undefined
  ) {
    throw new Error('Invalid segment index');
  }

  // Handle edge case where input range has no width
  if (inputMax === inputMin) {
    return outputMin;
  }

  // Linear interpolation (with extrapolation support unless clamped)
  const ratio = (value - inputMin) / (inputMax - inputMin);
  const result = outputMin + ratio * (outputMax - outputMin);

  // Apply clamping if requested
  if (options?.clamp) {
    const minOutput = Math.min(outputRange[0] ?? 0, outputRange[outputRange.length - 1] ?? 0);
    const maxOutput = Math.max(outputRange[0] ?? 0, outputRange[outputRange.length - 1] ?? 0);
    return Math.max(minOutput, Math.min(maxOutput, result));
  }

  return result;
}
/* eslint-enable security/detect-object-injection */

/**
 * Motion utility types
 * @module utils/motion/types
 */

/**
 * 2D point coordinates
 */
export interface Point2D {
  x: number;
  y: number;
}

/**
 * Spring physics configuration
 */
export interface SpringConfig {
  /** Mass of the spring (default: 1) */
  mass?: number;
  /** Stiffness of the spring (default: 100) */
  stiffness?: number;
  /** Damping coefficient (default: 10) */
  damping?: number;
  /** Initial velocity (default: 0) */
  velocity?: number;
}

/**
 * Spring physics state at a point in time
 */
export interface SpringState {
  /** Current position */
  position: number;
  /** Current velocity */
  velocity: number;
  /** Whether the spring has settled */
  done: boolean;
}

/**
 * Easing function type
 */
export type EasingFunction = (t: number) => number;

/**
 * Interpolation range
 */
export interface InterpolationRange {
  /** Input range (domain) */
  inputRange: number[];
  /** Output range (codomain) */
  outputRange: number[];
}
